builder.Services.AddApiVersioning(options =>
{
    options.DefaultApiVersion = new ApiVersion(1, 0);
    options.AssumeDefaultVersionWhenUnspecified = true;
    options.ReportApiVersions = true;
    options.ApiVersionReader = ApiVersionReader.Combine(
        new UrlSegmentApiVersionReader(),
        new HeaderApiVersionReader("api-version"),
        new QueryStringApiVersionReader("api-version"));
})
.AddApiExplorer(options =>
{
    options.GroupNameFormat = "'v'VVV";
    options.SubstituteApiVersionInUrl = true;
});

[ApiController]
[Route("api/v{version:apiVersion}/shipments")]
public class ShipmentsV1Controller : ControllerBase
{
    [HttpGet("{id}")]
    [MapToApiVersion(1.0)]
    public ShipmentV1Dto Get(int id) => new(id, "InTransit");
}

[ApiController]
[Route("api/v{version:apiVersion}/shipments")]
public class ShipmentsV2Controller : ControllerBase
{
    [HttpGet("{id}")]
    [MapToApiVersion(2.0)]
    public ShipmentV2Dto Get(int id) => new(id, ShipmentStatus.InTransit, DateTime.UtcNow);
}

record ShipmentV1Dto(int Id, string Status);
enum ShipmentStatus { InTransit, Delivered }
record ShipmentV2Dto(int Id, ShipmentStatus Status, DateTime LastUpdatedUtc);

var v1 = app.NewVersionedApi("Orders").MapGroup("/api/v{version:apiVersion}/orders")
    .HasApiVersion(1, 0);
var v2 = app.NewVersionedApi("Orders").MapGroup("/api/v{version:apiVersion}/orders")
    .HasApiVersion(2, 0);

v1.MapGet("/{id}", (int id) => Results.Ok(new { id, total = "99.00" }));
v2.MapGet("/{id}", (int id) => Results.Ok(new { id, total = 99.00m, currency = "USD" }));
